            if 0 <= nr < H and 0 <= nc < W:
                yield nr, nc

    # Find connected components of same nonzero color
    seen = [[False] * W for _ in range(H)]
    comps = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and not seen[r][c]:
                color = grid[r][c]
                stack = [(r, c)]
                seen[r][c] = True
                cells = []
                while stack:
                    cr, cc = stack.pop()
                    cells.append((cr, cc))
                    for nr, nc in neighbors(cr, cc):
                        if not seen[nr][nc] and grid[nr][nc] == color:
                            seen[nr][nc] = True
                            stack.append((nr, nc))
                rs = [x for x, _ in cells]
                cs = [y for _, y in cells]
                r0, r1 = min(rs), max(rs)
                c0, c1 = min(cs), max(cs)
                comps.append({
                    "color": color,
                    "cells": cells,
                    "set": set(cells),
                    "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                    "h": r1 - r0 + 1, "w": c1 - c0 + 1,
                    "size": len(cells),
                    "center_r": sum(rs) / len(rs),
                    "center_c": sum(cs) / len(cs),
                })

    if not comps:
        return grid

